//Small helpers shared across CMS publishers.

/**
 * Appends the audit-generated JSON-LD structured data as a <script> tag at
 * the end of the post's HTML content.
 *
 * Originally lived only in wordpress.ts. Extracted here because
 * `payload.seoSchema` was being silently dropped by publishers that accept
 * raw HTML content (webflow, wix, gohighlevel) — they never referenced the
 * field at all, so schema markup generated by the technical-audit phase
 * never reached the live page for those platforms. Any publisher whose API
 * takes a plain HTML content field should use this instead of re-deriving
 * its own version.
 *
 * Not used by sanity.ts / custom-api.ts / framer.ts — those pass
 * `seoSchema` through as structured JSON in the request payload itself
 * (the receiving system is expected to render it), not embedded in HTML.
 */
export function injectSchema(content: string, schema: Record<string, unknown> | undefined): string {
  if (!schema) return content;
  const scriptTag = `\n<script type="application/ld+json">\n${JSON.stringify(schema, null, 2)}\n</script>`;
  return content + scriptTag;
}
